#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float2 amzp_position;
uniform float amzp_size;
uniform float amzp_stretch;
uniform float amzp_colorMode;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
layout(color) uniform half4 amzp_color3;
uniform float amzp_alpha;
uniform float amzp_blendMode;
uniform float amzp_alphaScale;
uniform float amzp_copyAlpha;
uniform float amzp_lineWidth;
uniform float amzp_feather;
uniform float amzp_angle;
uniform float amzp_screenSpace;
        const float PI = 3.14159;
        const float ulp = PI/240.;
        const float2 hexRatio = float2(1.0, 1.73);
        const float2 hexRatioNorm = normalize(hexRatio);
        float hexDist(float2 p) {
            return max(dot(abs(p), hexRatioNorm), abs(p.x));
        }
        void hexTile(float2 st, out float2 uv, out float2 huv, out float2 id) {
            float2 grid = mod(st, hexRatio)-hexRatio/2.;
            float2 offsetGrid = mod(st-hexRatio/2., hexRatio)-hexRatio/2.;
            uv = length(grid) < length(offsetGrid) ? grid : offsetGrid;
            huv = float2(atan(uv.x, uv.y), (.5-hexDist(uv))*2.);
            id = float2(st.x-uv.x, st.y-uv.y);
        }
        float2x2 rot(float a) {
            float c = cos(a);
            float s = sin(a);
            return float2x2(
                c, -s,
                s, c
            );
        }
        float2 l2s( float2 v, float4x4 acLTS ) {
            return (float4(v,0.,1.)*acLTS).xy;
        }
        void amzRender() {
            float4 texColor = amzTexture(0,amzScreenNorm());
            float2 st;
            if((amzp_screenSpace>0.5)) {
                st = amzScreenNorm();
                st -= 0.5;
                st.x *= screen.zw.x/screen.zw.y;
            } else {
                st = amzLayerNorm();
                st -= 0.5;
                st.x *= layer.x/layer.y;
            }
            float2 scale = float2(amzp_size/100., amzp_size/100. * amzp_stretch);
            float2 amzLocal_pos = (amzp_position/500.) * float2(1., -1.);
            st /= scale;
            st *= rot(amzp_angle * 0.0174533);
            amzLocal_pos *= rot(-amzp_angle * 0.0174533);
            float2 modPos = mod(amzLocal_pos,hexRatio*2.);
            float2 basePos = amzLocal_pos - modPos;
            float2 stepPos = basePos;
            st -= modPos;
            float2 uv;
            float2 huv;
            float2 id;
            hexTile(st,uv,huv,id);
            id -= stepPos;
            id += 1000.;
            float2 screenCoord;
            screenCoord = st-uv;
            screenCoord += modPos;
            screenCoord *= rot(-amzp_angle * 0.0174533);
            screenCoord *= scale;
            screenCoord.x /= layer.x/layer.y;
            screenCoord += 0.5;
            screenCoord = l2s(screenCoord,amzLayerToScreen());
            float4 centerColor = amzTexture(0,screenCoord);
            float pp;
            if( (amzp_alphaScale>0.5) ) {
                pp = max(1. - centerColor.a, amzp_lineWidth);
            } else if (int(amzp_blendMode) == 3) {
                pp = max(1. - step(0.001,centerColor.a), amzp_lineWidth);
            } else {
                pp = amzp_lineWidth;
            }
            pp = ((pp-0.5) * (1.0+amzp_feather)) + 0.5;
            float p = smoothstep(pp-amzp_feather/2.,pp+amzp_feather/2.,huv.y);
            float4 color;
            if( int(amzp_colorMode) == 0 ) {
                color = centerColor;
            } else if ( int(amzp_colorMode) == 1 ) {
                color = amzp_color1;
                color.rgb *= color.a;
            } else if ( int(amzp_colorMode) == 2 ) {
                float ys = step(1.73/2.,mod(id.y, 1.73));
                color = mix(amzp_color1,amzp_color2,ys);
                color.rgb *= color.a;
            } else if ( int(amzp_colorMode) == 3 ) {
                float ys = step(1.73/2.,mod(id.y, 1.73));
                color = amzp_color1;
                color = mix(color,amzp_color2,step(0.33,mod(id.x + ys*1.66, 3.)));
                color = mix(amzp_color3,color,step(0.33,mod(id.x + 1.16 + ys*1.66, 3.)));
                color.rgb *= color.a;
            } else if ( int(amzp_colorMode) == 4 ) {
                color = amzp_color1;
                color = mix(color,amzp_color3,smoothstep( PI*2./3. - ulp, PI*2./3. + ulp, huv.x + PI));
                color = mix(color,amzp_color2,smoothstep( PI/3. - ulp, PI/3. + ulp, huv.x));
                color.rgb *= color.a;
            } else if ( int(amzp_colorMode) == 5 ) {
                float section = floor((huv.x + PI) * 3. / PI);
                if( section < 1. ) {
                    color = amzp_color1;
                } else if (section < 2. ) {
                    color = amzp_color2;
                } else if (section < 3. ) {
                    color = amzp_color1;
                } else if (section < 4. ) {
                    color = amzp_color3;
                } else if (section < 5. ) {
                    color = amzp_color1;
                } else {
                    color = amzp_color2;
                }
                color.rgb *= color.a;
            } else if ( int(amzp_colorMode) == 6 ) {
                float section = floor((huv.x + PI) * 6. / PI);
                if( section < 1. ) {
                    color = amzp_color1;
                } else if (section < 5. ) {
                    color = amzp_color2;
                } else if (section < 9. ) {
                    color = amzp_color3;
                } else {
                    color = amzp_color1;
                }
                color.rgb *= color.a;
            }
            color *= p;
            if( (amzp_copyAlpha>0.5) ) {
                color *= centerColor.a;
            }
            color *= amzp_alpha;
            float4 result;
            if( int(amzp_blendMode)==0 ) {
                color *= texColor.a;
                result = color + (texColor*(1.0-color.a));
            } else if( int(amzp_blendMode)==1 ) {
                float4 c = color + float4(1.)*(1.-color.a);
                result = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
            } else if( int(amzp_blendMode)==2 ) {
                result = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-color.rgb)),1.0) * texColor.a;
            } else if( int(amzp_blendMode)==3 ) {
                result = color;
            } else if( int(amzp_blendMode)==4 ) {
                result = texColor * (1.0-p);
            } else if( int(amzp_blendMode)==5 ) {
                float3 top = color.rgb / color.a;
                float3 bot = texColor.rgb / texColor.a;
                float3 t = smoothstep(0.5,0.5,bot);
                float3 r3 =
                        t * (1. - (1.-2.*(bot-0.5)) * (1.-top)) +
                        (1.-t) * ((2.*bot) * top);
                float4 r4 = float4(r3, 1.0) * color.a * texColor.a;
                result = texColor * (1.-r4.a) + r4;
            }
            amzOutput = result;
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
